package com.italiano2774.nativeapp;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class PrepositionRepository{private final List<PrepositionExercise> all=new ArrayList<>();public PrepositionRepository(Context c){try{BufferedReader br=new BufferedReader(new InputStreamReader(c.getAssets().open("preposition_exercises.json"),StandardCharsets.UTF_8));StringBuilder sb=new StringBuilder();String l;while((l=br.readLine())!=null)sb.append(l);JSONArray a=new JSONArray(sb.toString());for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);PrepositionExercise e=new PrepositionExercise();e.id=o.optString("id","prep"+i);e.sentence=o.optString("sentence");e.chinese=o.optString("zh");e.answer=o.optString("answer");e.explanation=o.optString("explanation");JSONArray os=o.optJSONArray("options");if(os!=null)for(int j=0;j<os.length();j++)e.options.add(os.optString(j));if(!e.sentence.isEmpty()&&e.options.size()>=2)all.add(e);}}catch(Exception e){throw new RuntimeException("Failed to load preposition_exercises.json",e);}}public List<PrepositionExercise> session(int n){List<PrepositionExercise>x=new ArrayList<>(all);Collections.shuffle(x);return new ArrayList<>(x.subList(0,Math.min(n,x.size())));}public int size(){return all.size();}}
